head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setGridWidth]<br/>GridView 컴포넌트의 너비(Width)를 설정합니다.",
    "validation" : [
        "width(필수) 파라미터로 GridView 컴포넌트의 너비(Width)를 픽셀(px)단위로 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 컬럼 폭 합(1200px) > 그리드 너비(400px)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (col1~col6, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] par_width 값(200 / 400 / 600 / 900) 선택 후 (setGridWidth) 클릭\n[확인] 그리드 컨테이너 offsetWidth 가 설정한 px 로 적용"', '', 'label1');

    // target 생성 (6컬럼 × 200px = 1200px, 초기 너비 400px)
    await scwin.createGridView();
}



// 가로 스크롤 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [];
    for (var i = 1; i <= 6; i++) {
        rows.push({ col1: "A" + i, col2: "B" + i, col3: "C" + i, col4: "D" + i, col5: "E" + i, col6: "F" + i });
    }
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (가로 넘침 그리드)
scwin.createGridView = async function () {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:400px;height:250px;">';
    s += '<w2:caption style="" id="caption1" value="setGridWidth 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="200" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column5" value="col5"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column6" value="col6"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="200" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col5" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col6" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// setGridWidth 호출 : par_width(필수) 값을 그리드 너비(px)로 설정 후 적용값 확인
//  - 확인 : 그리드 컨테이너 offsetWidth 가 설정한 px 로 적용 (getGridWidth 미제공 → DOM 측정)
scwin.btn_setGridWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let vWidth = parseInt(par_width.getValue(), 10);

    // 메소드 실행
    target1.setGridWidth(vWidth);

    setTimeout(function () {
        // 그리드 컨테이너 실제 너비
        let gridEl = document.querySelector("[id$='target1']");
        let appliedWidth = gridEl ? gridEl.offsetWidth : 0;

        bottom.setReturnValue("[설정값 width=" + vWidth + "px] 그리드 offsetWidth=" + appliedWidth + "px");
    }, 300);
}
